import requestsclass FrappeAPI:    def __init__(self):        self.base_url = "http://localhost:8000"        self.session = requests.Session()    def login(self, username, password):        url = self.base_url + "/api/method/login"        data = {            "usr": username,            "pwd": password        }        response = self.session.post(            url,            data=data        )        return response    def get_leads(self):        url = self.base_url + "/api/resource/CRM%20Lead"        response = self.session.get(url)        return response    def create_lead(self, data):        url = self.base_url + "/api/resource/CRM%20Lead"        response = self.session.post(            url,            json=data        )        return response